#include "gba/genres/TurnStrategyModule.h"
#include "gba/genres/GenreUtil.h"
#include <algorithm>
#include <cmath>
#include <sstream>

namespace gba { using namespace genreutil;
std::string TurnStrategyModule::genre()const{return "turn_strategy";}
std::vector<ParameterSpec>TurnStrategyModule::balanceParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&u:arrayObjects(g.raw,"units")){auto id=str(u,"id");p.push_back(spec("unit."+id+".costMul",1,.5,2,.16));p.push_back(spec("unit."+id+".powerMul",1,.45,2.5,.18));p.push_back(spec("unit."+id+".rangeMul",1,.65,1.6,.14));p.push_back(spec("unit."+id+".roleMul",1,.5,2.5,.18));}p.push_back(spec("enemyPowerMul",1,.55,2,.17));p.push_back(spec("incomeMul",1,.6,1.7,.14));return p;}
std::vector<ParameterSpec>TurnStrategyModule::strategyParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&u:arrayObjects(g.raw,"units"))p.push_back(spec("pref."+str(u,"id"),1,.02,4,.22));p.push_back(spec("aggression",1,.2,2,.18));p.push_back(spec("reserve",.2,0,.7,.15));p.push_back(spec("counterBias",1,.2,2.5,.2));return p;}
SimulationResult TurnStrategyModule::simulate(const GameDefinition&g,const Genome&b,const Genome&s,std::uint64_t seed,int maxP)const{std::mt19937_64 rng(seed);SimulationResult r;r.strategyId=s.id;r.balanceId=b.id;r.seed=seed;auto units=arrayObjects(g.raw,"units");auto rules=g.raw["rules"];double gold=attr(rules,"startGold",100),income=gold,baseHp=attr(rules,"baseHp",100),startHp=baseHp;std::map<std::string,double>army;double early=baseHp;
 for(int round=1;round<=maxP;++round){double inc=attr(rules,"incomePerRound",20)*gene(b,"incomeMul")*(1+.01*round);gold+=inc;income+=inc;double enemyRole=(round%3==0)?1:(round%5==0)?2:0;double enemyPower=(attr(rules,"enemyPowerBase",18)+round*attr(rules,"enemyPowerGrowth",2.3))*gene(b,"enemyPowerMul")*(.9+.2*rand01(rng));double reserve=gold*s.get("reserve",.2);int buys=0;while(buys<6){const Json*best=nullptr;double bu=-1,bc=0;for(const auto&u:units){auto id=str(u,"id"),role=str(u,"role","allround");double cost=attr(u,"cost",30)*gene(b,"unit."+id+".costMul");if(cost>gold-reserve)continue;double counter=1; if((enemyRole==1&&role=="ranged")||(enemyRole==2&&role=="tank"))counter=1+.6*s.get("counterBias",1);double util=s.get("pref."+id,1)*counter*attr(u,"power",10)*gene(b,"unit."+id+".powerMul")/std::max(1.0,cost);if(util>bu){bu=util;best=&u;bc=cost;}}if(!best)break;auto id=str(*best,"id");gold-=bc;army[id]++;r.usage[id]++;buys++;if(rand01(rng)<.3)break;}
 double power=0;for(const auto&u:units){auto id=str(u,"id"),role=str(u,"role","allround");double n=army[id];if(n<=0)continue;double range=gene(b,"unit."+id+".rangeMul");double roleBonus=gene(b,"unit."+id+".roleMul");double c=n*attr(u,"power",10)*gene(b,"unit."+id+".powerMul")*std::pow(range,.35)*roleBonus;power+=c;r.contribution[id]+=c;}
 double ratio=power/std::max(1.0,enemyPower);if(ratio<1){baseHp-=(1-ratio)*enemyPower*.12;}else{gold+=(ratio-1)*3;income+=(ratio-1)*3;}if(round==5)early=baseHp;r.progress=round;if(baseHp<=0){r.success=false;break;}}
r.success=r.progress>=maxP;r.earlySafety=clamp01(early/startHp);r.resourceIncome=std::max(1.0,income);r.resourceResidual=gold;r.score=r.progress*28+r.earlySafety*450+r.success*1000;return r;}
EvaluationSummary TurnStrategyModule::evaluateBalance(const GameDefinition&g,const Genome&b,const std::vector<SimulationResult>&runs)const{auto e=IGameModule::evaluateBalance(g,b,runs);e.fitness-=std::max(0.0,e.topShare-.48)*4500;e.fitness-=std::max(0.0,e.topPairShare-.75)*5500;e.fitness+=e.diversity*700;std::ostringstream o;o<<"TurnStrategy target="<<e.fitness<<" rounds="<<e.avgProgress<<" duo="<<e.topPairShare;e.explanation=o.str();return e;}
std::vector<Genome>TurnStrategyModule::targetedBalanceExperiments(const GameDefinition&g,const Genome&base,const EvaluationSummary&c,std::uint64_t&nid,int gen,std::mt19937_64&,double strength)const{std::vector<Genome>v;std::string hi,lo;double a=-1,z=1e99;for(const auto&u:arrayObjects(g.raw,"units")){auto id=str(u,"id");double q=c.meanContribution.count(id)?c.meanContribution.at(id):0,x=c.meanUsage.count(id)?c.meanUsage.at(id):0;if(q>a){a=q;hi=id;}if(x<z){z=x;lo=id;}}if(!hi.empty()&&!lo.empty()&&hi!=lo){Genome n=base;n.id=nid++;n.generation=gen;n.note="anti-unit-meta:"+hi+"->"+lo;n.genes["unit."+hi+".powerMul"]*=1-strength*.25;n.genes["unit."+lo+".powerMul"]*=1+strength*.3;n.genes["unit."+lo+".costMul"]*=1-strength*.1;v.push_back(n);}return v;}
}
